  FT["PH-H4076"] = {"id":"PH-H4076","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5273_1968.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"授予 Feliciana E. Alvarez 在奎松市建设、维护和运营制冰厂与冷藏库并分销销售所制冰和提供冷藏服务的特许权法案","en":"An Act Granting Feliciana E. Alvarez a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storages, and to Distribute and Sell Ice so Manufactured and Furnish Cold Storage Service in the City of Quezon","orig":"An Act Granting Feliciana E. Alvarez a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storages, and to Distribute and Sell Ice so Manufactured and Furnish Cold Storage Service in the City of Quezon"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5273","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5273_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4076-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions imposed by this Act, there is granted to Feliciana E. Alvarez, her successors or assigns, for a period of twenty-five years after the approval of this Act, the right, privilege and authority to construct, maintain and operate an ice plant and cold storages in the City of Quezon for the purpose of manufacturing ice and furnishing cold storage, and to sell and distribute the ice so manufactured and render cold storage service and facilities in the said city, and to collect a schedule of rates, prices and charges for the ice so manufactured, distributed and sold, and for the cold storage furnished which schedule of rates, prices and charges shall at all times be subject to regulation by the Public Service Commission."}},{"id":"PH-H4076-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All the machinery, equipment and appurtenances to be used by the grantee shall be modern, safe and first class in every respect."}},{"id":"PH-H4076-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"If the grantee shall not commence the manufacture of ice within two years from the approval of this Act, unless prevented by an act of God, or by force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee's control, this franchise shall become null and void."}},{"id":"PH-H4076-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This franchise is granted subject to the provisions of Commonwealth Act Numbered One hundred forty-six, as amended, only with respect to the fixing or rates, and with the understanding and upon the condition that it shall be subject to amendment, alteration and/or repeal by the Congress of the Philippines when public interest so requires."}},{"id":"PH-H4076-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In the event of any competing individual, association of persons, or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons or corporation."}},{"id":"PH-H4076-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Feliciana E. Alvarez a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storages, and to Distribute and Sell Ice so Manufactured and Furnish Cold Storage Service in the City of Quezon","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4077"] = {"id":"PH-H4077","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5274_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将本格特省 Atok市镇 Paoay 小学的名称变更为Celo Haight 小学的法案","en":"An Act Changing the Name of Paoay Elementary School in the Municipality of Atok, Province of Benguet, to Celo Haight Elementary School","orig":"An Act Changing the Name of Paoay Elementary School in the Municipality of Atok, Province of Benguet, to Celo Haight Elementary School","vi":"Đạo luật đổi tên Trường tiểu học Paoay tại Thị trấn Atok, Tỉnh Benguet thành Trường tiểu học Celo Haight","th":"พระราชบัญญัติเปลี่ยนชื่อโรงเรียนประถมศึกษา Paoay ในเทศบาล Atok, จังหวัด Benguet เป็นโรงเรียนประถมศึกษา Celo Haight","id":"Undang-Undang mengubah nama Sekolah Dasar Paoay di Kotamadya Atok, Provinsi Benguet menjadi Sekolah Dasar Celo Haight","ms":"Akta menukar nama Sekolah Rendah Paoay di Perbandaran Atok, Wilayah Benguet menjadi Sekolah Rendah Celo Haight"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5274","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5274_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4077-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Paoay Elementary School located in the Municipality of Atok, Province of Benguet, is hereby changed to Celo Haight Elementary School."}},{"id":"PH-H4077-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Paoay Elementary School in the Municipality of Atok, Province of Benguet, to Celo Haight Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4078"] = {"id":"PH-H4078","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5275_1968.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在邦阿西楠省Bayambang市镇设立急诊医院并授权为此拨款的法案","en":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Bayambang, Province of Pangasinan, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Bayambang, Province of Pangasinan, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Cấp cứu tại Thị trấn Bayambang, Tỉnh Pangasinan, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลฉุกเฉินในเทศบาล Bayambang จังหวัด Pangasinan และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Gawat Darurat di Kotamadya Bayambang, Provinsi Pangasinan, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Kecemasan di Perbandaran Bayambang, Wilayah Pangasinan, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5275","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5275_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4078-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the direct supervision of the Director of Medical Services, an emergency hospital in the Municipality of Bayambang, Province of Pangasinan, to be known as Bayambang Emergency Hospital."}},{"id":"PH-H4078-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred sixty-nine. Thereafter, such sum as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H4078-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Bayambang, Province of Pangasinan, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4079"] = {"id":"PH-H4079","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5276_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将伊莎贝拉省Ramon市镇的政府所在地由Burgos村迁至该市镇Bugallon村，为此修订第3320号共和国法的法案","en":"An Act Transferring the Seat of Government of the Municipality of Ramon, Province of Isabela, from Barrio Burgos to Barrio Bugallon of Said Municipality, Amending for the Purpose Republic Act Numbered Thirty-Three Hundred and Twenty","orig":"An Act Transferring the Seat of Government of the Municipality of Ramon, Province of Isabela, from Barrio Burgos to Barrio Bugallon of Said Municipality, Amending for the Purpose Republic Act Numbered Thirty-Three Hundred and Twenty"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5276","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5276_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4079-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Thirty-three hundred and twenty is hereby amended to read as follows:\n\"Sec. 1. Barrios Bugallon, Burgos, San Miguel, San Sebastian, Raniag and Pagrang-ayan are separated from the Municipality of Santiago, and Barrios Oscariz, Nagbacalan and Bantug Petinez are separated from the Municipality of San Mateo, all in the Province of Isabela, and constituted into a new and separate municipality of said province to be known as the Municipality of Ramon. The seat of government of the municipality shall be located at the present site of Barrio Bugallon."}},{"id":"PH-H4079-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Transferring the Seat of Government of the Municipality of Ramon, Province of Isabela, from Barrio Burgos to Barrio Bugallon of Said Municipality, Amending for the Purpose Republic Act Numbered Thirty-Three Hundred and Twenty","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4080"] = {"id":"PH-H4080","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5277_1968.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"为第二司法区增设一名法官主持拉乌尼翁初审法院，为此修订1948年《司法法》第50条与第52条并授权为此拨款的法案","en":"An Act Providing for One Additional Judge for the Second Judicial District to Preside Over the Court of First Instance of La Union, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948, and Authorizing the Appropriation of Funds for the Purpose","orig":"An Act Providing for One Additional Judge for the Second Judicial District to Preside Over the Court of First Instance of La Union, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948, and Authorizing the Appropriation of Funds for the Purpose"},"level":"law","status":"active","topics":["labor","judiciary"],"docNumber":"Republic Act No. 5277","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5277_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4080-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The second paragraph of Section fifty of Republic Act Numbered Two hundred ninety-six, otherwise known as the Judiciary Act of 1948, as amended, is further amended to read as follows:\n\"Nineteen judges shall be commissioned for the Second Judicial District. Four judges shall preside over the Court of First Instance of Ilocos Norte; four judges shall preside over the Court of First Instance of Ilocos Sur; one judge shall preside over the Court of First Instance of Abra; three judges shall preside over the Court of First Instance of the City of Baguio and the Subprovince of Benguet, to be known as judges of the first, second, and third branches thereof; three judges shall preside over the Court of First Instance of the Mountain Province with jurisdiction covering the whole of Mountain Province except the City of Baguio and the Subprovince of Benguet; four judges shall preside over the Court of First Instance of La Union and shall be known as the judges of the first, second, third and fourth branches thereof, respectively."}},{"id":"PH-H4080-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The second subparagraph of the second paragraph of Section fifty-two of the same Act, as amended, is further amended to read as follows:\n\"For the Second Judicial District, three judges shall be stationed in the City of Laoag; one judge shall be stationed in the Municipality of Batac, Province of Ilocos Norte; two judges in the Municipality of Vigan, Province of Ilocos Sur; one judge in the Municipality of Narvacan, same province; one judge in the Municipality of Candon, same province; two judges in the City of Baguio; one judge in the Municipality of La Trinidad, Subprovince of Benguet; one judge in the Municipality of Bontoc, Subprovince of Bontoc; one judge in the Municipality of Kiangan, Subprovince of Ifugao; one judge in the Municipality of Tabuk, Subprovince of Kalinga; one judge in the Municipality of Bengued, Province of Abra; two judges in the Municipality of San Fernando, Province of La Union; one judge in the Municipality of Agoo, same province; and one judge in the Municipality of Balaoan, same province.\""}},{"id":"PH-H4080-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby authorized to be appropriated, out of funds in the National Treasury not otherwise appropriated, forty thousand pesos, or so much thereof as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H4080-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for One Additional Judge for the Second Judicial District to Preside Over the Court of First Instance of La Union, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948, and Authorizing the Appropriation of Funds for the Purpose","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
