  FT["PH-H4122"] = {"id":"PH-H4122","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5319_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将伊洛伊洛省兰布瑙市镇帕西格-纳蒂维达德小学的名称变更为Filemon Lebero纪念小学的法案","en":"An Act Changing the Name of Pasig-Natividad Elementary School in the Municipality of Lambunao, Province of Iloilo, to Filemon Lebero Memorial Elementary School","orig":"An Act Changing the Name of Pasig-Natividad Elementary School in the Municipality of Lambunao, Province of Iloilo, to Filemon Lebero Memorial Elementary School","vi":"Đạo luật đổi tên Trường tiểu học Pasig-Natividad tại Thị trấn Lambunao, Tỉnh Iloilo thành Trường tiểu học Filemon Lebero Memorial","th":"พระราชบัญญัติเปลี่ยนชื่อโรงเรียนประถมศึกษา Pasig-Natividad ในเทศบาล Lambunao, จังหวัด Iloilo เป็นโรงเรียนประถมศึกษา Filemon Lebero Memorial","id":"Undang-Undang mengubah nama Sekolah Dasar Pasig-Natividad di Kotamadya Lambunao, Provinsi Iloilo menjadi Sekolah Dasar Filemon Lebero Memorial","ms":"Akta menukar nama Sekolah Rendah Pasig-Natividad di Perbandaran Lambunao, Wilayah Iloilo menjadi Sekolah Rendah Filemon Lebero Memorial"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5319","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5319_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4122-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Pasig-Natividad Elementary School in the Municipality of Lambunao, Province of Iloilo, is hereby changed to Filemon Lebero Memorial Elementary School."}},{"id":"PH-H4122-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Pasig-Natividad Elementary School in the Municipality of Lambunao, Province of Iloilo, to Filemon Lebero Memorial Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4123"] = {"id":"PH-H4123","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5320_1968.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订Calbayog市宪章的法案","en":"An Act to Revise the Charter of the City of Calbayog","orig":"An Act Amending the First Paragraph of Section Thirty-Two, and Section Thirty-Three of Republic Act Numbered Thirty-Two Hundred Seventy-Nine, Entitled \"An Act to Revise the Charter of the City of Calbayog\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5320","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5320_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4123-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of Section thirty-two of Republic Act Numbered Thirty-two hundred seventy-nine, otherwise known as the Revised Charter of the City of Calbayog, as amended to read as follows:\n\"Sec. 32. The Chief of Police. — His powers and duties. There shall be a chief of police who shall have charge of the police department and shall receive a salary of five thousand four hundred pesos per annum. He shall be assisted in the discharge of his duties by a deputy chief of police who shall receive a salary of not less than three thousand six hundred pesos per annum. The chief of police shall have the following powers and duties:"}},{"id":"PH-H4123-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section thirty-three of the same Act is amended to read as follows:\n\"Sec. 33. Chief of Secret Service. — There shall be a chief of the secret service who shall, under the chief of police, have charge of the detective work of the department and of the detective force of the city, and shall perform such other duties as may be assigned to him by the chief of police or prescribed by law or ordinance. The chief of the secret service shall receive a salary of not less than two thousand four hundred pesos per annum."}},{"id":"PH-H4123-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Revise the Charter of the City of Calbayog","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4124"] = {"id":"PH-H4124","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5321_1968.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"授予 World-Wide Communications，Inc. 设立并运营国内与国际电信无线电台的特许经营权法案","en":"An Act Granting the World-Wide Communications, Inc. a Franchise to Establish Radio Stations for Domestic and International Telecommunications","orig":"An Act Granting the World-Wide Communications, Inc. a Franchise to Establish Radio Stations for Domestic and International Telecommunications","vi":"Đạo luật cấp quyền khai thác cho World-Wide Communications, Inc. để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ World-Wide Communications, Inc. เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada World-Wide Communications, Inc. untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio di Filipina","ms":"Akta memberikan francais kepada World-Wide Communications, Inc. untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio di Filipina"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 5321","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5321_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4124-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and to the provisions not inconsistent herewith, of Act Numbered Three thousand eight hundred and forty-six, entitled \"An Act Providing for the Regulation of Radio Stations and Radio Communications in the Philippine Islands and for other Purposes,\" Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, there is hereby granted to the World-Wide Communications Inc., its successors or assigns the right and privilege of constructing, installing, establishing and operating in the Philippines and at such places as the grantee may select, subject to the approval of the Department of Public Works and Communications or any competent authority who is now or shall in the future authorized to give said approval, stations for international telecommunications, public coastal radio stations with corresponding relay stations, public fixed and public based and land mobile stations and radio paging systems and all stations authorized to receive and transmit via radiotelephony (voice) and/or radiotelegraphy, and/or any other type or mode of reception and transmission, visual, electronic, electrical or other means and stations in the broadcasting, television, radiophoto and facsimile services, both domestic and international and stations to provide and/or lease radio telegraph, facsimile, teletype or any other communication services to the public and/or public or private entities, persons, firms, companies, and corporations within their internal framework and/or to communicate between said internal stations and grantee's network station/stations, including, without limitations as to the generality thereof, stations operating via satellite system, with the Philippines or in other countries and with vessels and aircraft over the air, irrespective of whether such vessels or aircrafts are within or without the Philippines."}},{"id":"PH-H4124-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the construction of said stations or any of them on any land of the public domain upon such terms and conditions as he may prescribe."}},{"id":"PH-H4124-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date the first of said stations shall be placed in operation, and is granted upon the express condition that the same shall be void unless the construction of said stations be begun within two years from the date of approval of this Act and be completed within four years, from said date: Provided, However, That suitable receiving and transmitting frequencies shall have been assigned to the grantee, upon proper request to the designated authorities specifically empowered to discharge such functions."}},{"id":"PH-H4124-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"a) Subject to provisions and limitations hereof and other applicable laws, grantee shall, upon proper request to the government authorities assigned to act on such matters, be assigned suitable receiving and transmitting frequencies. This franchise shall not take effect nor shall any powers hereunder be exercised by the grantee until such frequencies shall have been allotted to the grantee and licensed for its use.\nb) The Secretary of Public Works and Communications, on reasonable notice to grantee, may at any time change, cancel, or modify, in whole or in part, any or all of the allotments of frequencies or wave lengths so assigned. He may take such action (1) whenever in his judgment such frequencies and wave lengths have been used, or there is danger that they will be used by the grantee to impair electrical communications, or stifle competition to obtain a monopoly in electrical communication, or to otherwise violate the laws, and public policy of the Republic of the Philippines; (2) whenever in his judgment, the public interests require that such frequencies or wave lengths should be used for other purposes than those of the grantee, either by the government or by other individuals and/or entities licensed by it; and (3) whenever in his judgment, for any reason, the public interests of the Philippines so require."}},{"id":"PH-H4124-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The stations of the grantee shall be constructed and operated and the wave lengths so selected as to avoid interference with existing stations and to permit the expansion of the grantee's services."}},{"id":"PH-H4124-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order to cause the closing of the grantee's stations or to authorize the temporary use and operation thereof by any department of the government upon payment of just compensation to the grantee for such use."}},{"id":"PH-H4124-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to persons or to property, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H4124-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, using or occupying of any land except as is required for the actual necessary purposes for which this franchise is granted."}},{"id":"PH-H4124-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall keep an account of the gross receipts of its business and shall furnish the Auditor General and the Treasurer of the Philippines a copy each of such account not later than the fifteenth day of April of each year for the preceding year. All the books and accounts of the grantee pertaining to its business shall be subject to the official inspection of the Auditor General or his authorized representatives, and the audit and approval of such accounts shall be final and conclusive evidence as to the amount of the gross receipts, except that the grantee shall have the right to appeal to the courts of the Philippines under the terms and conditions provided in the laws of the Philippines."}},{"id":"PH-H4124-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The right is hereby reserved to the Government of the Philippines, through the Public Service Commission, or such other government agency as may hereafter be duly authorized, to fix the maximum rates or charges to be charged by the grantee."}},{"id":"PH-H4124-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall file a bond in the amount of twenty-five thousand pesos to guarantee faithful compliance and performance of grantee's obligations hereunder. If, after two years from the date of approval of this Act the grantee shall have fulfilled said obligations, or as soon thereafter as the grantee shall have fulfilled the same, the aforesaid bond shall be cancelled by the Government."}},{"id":"PH-H4124-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of or sell this franchise or the rights or privileges acquired hereunder to any person, firm, company, corporation or other entity, nor merge with any other person, company or corporation organized for the same purpose without the approval first of the Congress of the Philippines. Any corporation to which this franchise may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or entity."}},{"id":"PH-H4124-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when public interest so requires and shall not be interpreted as an exclusive grant of the privileges services herein provided. Any term or terms or authorized services more favorable than those herein granted, that in the past have been granted or in the future might be granted in a similar franchise or temporary permit by Congress to any competing person, natural or juridical, tending to place the herein grantee at any disadvantage, shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing person."}},{"id":"PH-H4124-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"In consideration of this franchise and rights hereby granted and any provision of law to the contrary notwithstanding, the grantee shall pay the same taxes as are now or may hereafter be required by law from other individuals, copartnerships, private, public or quasi-public associations, corporations, or joint-stock companies, operating under a similar franchise on real estate, buildings and other personal property, radio equipment, machinery and spare parts needed in connection with the business of the grantee. In consideration of this franchise, a tax equal to two per centum of all gross receipts from the business transacted under this franchise by the grantee shall be paid to the Treasurer of the Philippines each year, within ten days after assessment as provided in this Act."}},{"id":"PH-H4124-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the World-Wide Communications, Inc. a Franchise to Establish Radio Stations for Domestic and International Telecommunications","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4125"] = {"id":"PH-H4125","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5322_1968.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予米沙鄢大学在宿务市及菲律宾任何其他地方为教育、科学、文化与商业目的运营无线电广播与电视站的特许经营权法案","en":"An Act Granting the University of the Visayas a Franchise to Construct, Maintain, and Operate Radio Broadcasting and Television Stations in Cebu City and in Any Other Place Within the Philippines for Educational, Scientific, Cultural and Commercial Purposes","orig":"An Act Granting the University of the Visayas a Franchise to Construct, Maintain, and Operate Radio Broadcasting and Television Stations in Cebu City and in Any Other Place Within the Philippines for Educational, Scientific, Cultural and Commercial Purposes","vi":"Đạo luật cấp quyền khai thác cho University of the Visayas để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ University of the Visayas เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada University of the Visayas untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Filipina","ms":"Akta memberikan francais kepada University of the Visayas untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Filipina"},"level":"law","status":"active","topics":["investment","trade","education"],"docNumber":"Republic Act No. 5322","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5322_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4125-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and of Act Numbered Three thousand eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Three thousand nine hundred ninety-seven known as Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as Public Service Act, and their amendments, and other applicable laws not inconsistent with this Act, the University of the Visayas is hereby granted a franchise to construct, maintain and operate radio broadcasting and television stations in Cebu and in other parts of the Philippines for educational, scientific, cultural and commercial purposes as well as for public interest."}},{"id":"PH-H4125-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date the said stations shall be put in operation and is granted upon the express condition that the same shall be void unless the construction of at least one radio broadcasting station or one television station be begun in one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H4125-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall provide adequate public service time to enable the government, through the grantee's stations, to reach the population on important issues, shall assist in the functions of commercial, public information and education, shall conform to the ethics of honest enterprise, and shall not use its stations for the dissemination of deliberately false information or wilful misrepresentation, or to the detriment of public health and morals, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H4125-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee's radio broadcasting and television stations shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used under this franchise and issued to the grantee a license for such use."}},{"id":"PH-H4125-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee's radio and television stations shall be so constructed and operated and the wave lengths so selected to avoid interference with existing radio and television stations and to permit the expansion of grantee's services."}},{"id":"PH-H4125-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace and order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the government without compensating the grantee for their use during the period when they shall be so operated."}},{"id":"PH-H4125-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall be liable to pay the same taxes, unless exempted therefrom, on its real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter required to pay by law. It shall be liable further to pay all other taxes as provided in the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H4125-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance of this franchise shall be given in writing by the grantee within six months after approval of this Act. When so accepted, the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H4125-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act or scene or other matters to be broadcast and/or telecast from its stations; but if any such play, speech, act or scene or other matters should constitute a violation of the law or infringement of private right, the grantee shall be free from any liabilities, civil or criminal, for such speech, play, act or scene or other matters being broadcast: Provided, That the grantee, during any broadcast and/or telecast, shall cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast, if the tendency thereof is to propose and/or incite treason, rebellion, or sedition, or the language used therein or the theme is indecent or immoral."}},{"id":"PH-H4125-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not lease, transfer, sell, assign or grant the usufruct of this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose without the prior approval from the Congress of the Philippines. Any corporation to which this franchise may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial entity or legal entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions, and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H4125-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The franchise hereby granted shall be subject to amendments, alteration or repeal by the Congress of the Philippines when public interest so requires and shall not be interpreted as an exclusive grant of the privilege herein provided."}},{"id":"PH-H4125-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the University of the Visayas a Franchise to Construct, Maintain, and Operate Radio Broadcasting and Television Stations in Cebu City and in Any Other Place Within the Philippines for Educational, Scientific, Cultural and Commercial Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4126"] = {"id":"PH-H4126","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5323_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Calubian市","en":"An Act Creating Certain Barrios in the Municipality of Calubian, Province of Leyte","orig":"An Act Creating Certain Barrios in the Municipality of Calubian, Province of Leyte","vi":"Đạo luật thành lập các Barrio tại Đô thị Calubian, Tỉnh Leyte","th":"พระราชบัญญัติจัดตั้งบาริโอหลายแห่ง ในเทศบาล Calubian จังหวัด Leyte","id":"Undang-Undang membentuk beberapa Barrio di Kotamadya Calubian, Provinsi Leyte","ms":"Akta menubuhkan beberapa Barrio di Perbandaran Calubian, Wilayah Leyte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5323","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5323_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4126-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Calubian, Province of Leyte, are hereby converted into barrios of said municipality, to wit:\n(a) The sitio of Gantonghao is converted into a distinct and independent barrio of said municipality, to be known as Barrio Gantonghao;\n(b) The sitio of Malobago is converted into a distinct and independent barrio of said municipality, to be known as Barrio Malobago;\n(c) The sitio of Dulao is converted into a distinct and independent barrio of said municipality, to be known as Barrio Dulao;\n(d) The sitio of Petrolio (Boundary C-SI Rd.) is converted into a distinct and independent barrio of said municipality, to be known as Barrio Petrolio;\n(e) The sitio of Pates (Busawon) is converted into a distinct and independent barrio of said municipality, to be known as Barrio Pates;\n(f) The sitio of Abanilla (Uson) is converted into a distinct and independent barrio of said municipality, to be known as Barrio Abanilla;\n(g) The sitio of Obispo (Batuan Tomalestis) is converted into a distinct and independent barrio of said municipality, to be known as Barrio Obispo;\n(h) The sitio of Nipa is converted into a distinct and independent barrio of said municipality, to be known as Barrio Nipa;\n(i) The sitio of Tagharigue is converted into a distinct and independent barrio of said municipality, to be known as Barrio Tagharigue;\n(j) The sitio of Igang is converted into a distinct and independent barrio of said municipality, to be known as Barrio Igang;\n(k) The sitio of Cabalhin (Patag) is converted into a distinct and independent barrio of said municipality, to be known as Barrio Cabalhin;\n(l) The sitio of Matagok is converted into a distinct and independent barrio of said municipality, to be known as Barrio Matagok;\n(m) The sitio of Kawayanan is converted into a distinct and independent barrio of said municipality, to be known as Barrio Kawayanan;\n(n) The sitio of Kawayan Bugtong is converted into a distinct and independent barrio of said municipality, to be known as Barrio Kawayan Bugtong;\n(o) The sitio of Tuburan is converted into a distinct and independent barrio of said municipality, to be known as Barrio Tuburan;\n(p) The sitio of Pangpang is converted into a distinct and independent barrio of said municipality, to be known as Barrio Pangpang;\n(q) The sitio of Garrido (Laray Gamay) is converted into a distinct and independent barrio of said municipality, to be known as Barrio Garrido;\n(r) The sitio of Juson (Sangoraan) is converted into a distinct and independent barrio of said municipality, to be known as Barrio Juson;\n(s) The sitio of Patag (Benog) is converted into a distinct and independent barrio of said municipality, to be known as Barrio Patag;\n(t) The sitio of Pagatpat (Near Bunacan) is converted into a distinct and independent barrio of said municipality, to be known as Barrio Pagatpat;\n(u) The sitio of Railes is converted into a distinct and independent barrio of said municipality, to be known as Barrio Railes;\n(v) The sitio of Caneja (Batuan) is converted into a distinct and independent barrio of said municipality, to be known as Barrio Caneja;\n(w) The sitio of Hda. Enaje is converted into a distinct and independent barrio of said municipality, to be known as Barrio Hda. Enaje;\n(x) The sitio of Anislagan is converted into a distinct and independent barrio of said municipality, to be known as Barrio Anislagan;\n(y) The sitio of Bunacan is converted into a distinct and independent barrio of said municipality, to be known as Barrio Bunacan;\n(z) The sitio of Caroyocan is converted into a distinct and independent barrio of said municipality, to be known as Barrio Caroyocan;\n(aa) The sitio of Inalad is converted into a distinct and independent barrio of said municipality, to be known as Barrio Inalad;\n(bb) The sitio of Laray is converted into a distinct and independent barrio of said municipality, to be known as Barrio Laray; and (cc) The sitio of Cas-ongan is converted into a distinct and independent barrio of said municipality, to be known as Barrio Cas-ongan;"}},{"id":"PH-H4126-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58"};
  FT["PH-H4127"] = {"id":"PH-H4127","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5324_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Tayug市","en":"An Act Creating the Barrio of Toketek in the Municipality of Tayug, Province of Pangasinan","orig":"An Act Creating the Barrio of Toketek in the Municipality of Tayug, Province of Pangasinan","vi":"Đạo luật thành lập một Barrio Toketek tại Đô thị Tayug, Tỉnh Pangasinan","th":"พระราชบัญญัติจัดตั้งบาริโอ Toketek ในเทศบาล Tayug จังหวัด Pangasinan","id":"Undang-Undang membentuk sebuah Barrio Toketek di Kotamadya Tayug, Provinsi Pangasinan","ms":"Akta menubuhkan sebuah Barrio Toketek di Perbandaran Tayug, Wilayah Pangasinan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5324","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5324_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4127-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Toketek in the Municipality of Tayug, Province of Pangasinan, is hereby converted into a barrio of said municipality to be known as Barrio Toketek."}},{"id":"PH-H4127-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58"};
  FT["PH-H4128"] = {"id":"PH-H4128","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5326_1968.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"修订第3470号共和国法若干条款的法案","en":"An Act Amending Certain Sections of Republic Act Numbered Three Thousand Four Hundred Seventy","orig":"An Act Amending Certain Sections of Republic Act Numbered Three Thousand Four Hundred Seventy","vi":"Đạo luật sửa đổi một số điều của Đạo luật Cộng hòa số 3470","th":"พระราชบัญญัติแก้ไขเพิ่มเติมบางมาตราแห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 3470","id":"Undang-Undang mengubah beberapa pasal Undang-Undang Republik No. 3470","ms":"Akta meminda beberapa seksyen Akta Republik No. 3470"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5326","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5326_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4128-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eleven of Republic Act Numbered Three thousand four hundred seventy is hereby amended to read as follows:\n\"Sec. 11. Definition. — The term \"cottage industry\" as used in this Act shall mean an economic activity in a small scale carried on mainly in the homes or in other places for profit and mainly done with the help of the members of the family with capitalization not exceeding fifteen thousand pesos. The term shall also include economic activities carried on by students of public and private schools, within school premises, as a cooperative effort, under supervision of a teacher or other person approved by and acting under the supervision and control of school authorities, either as part of or in addition to ordinary vocational training, provided all profits shall accrue to the students working therein. It shall include the following: (1) fiber crafts, such as making of abaca ropes and twines, buntal fiber extracting and buri leaf braiding; (2) woodcraft such as making of wooden shoes, wooden fans, walking sticks (canes) and wood carvings; (3) hat weaving such as Calasiao, buri, rafia, karagomoy, buntal and bamboo hats, salakots and helmets; (4) mat weaving such as doormats, sleeping mats made of buri, pandan, balilan, and sabutan and other similar materials; (5) metal craft such as making of jewelries, knives, bolos, scissors, razors, silverwares, and brassworks; (6) ceramics such as making of potteries, hollow blocks, tiles, firebricks, clay stoves and other ceramic products; (7) shell craft such as making of sea shell buttons and coconut shell products; (8) bamboo and rattan crafts such as making of hammocks, basketry, making of sawali and other bamboo and rattan furniture and articles; (9) small agricultural hand tools such as plow points; (10) toy craft such as making of dolls and toys; (11) embroidery, dressmaking and tailoring industries; (12) needle craft (including knitting and crocheting); (13) loom weaving such as making of fish nets; making of mosquito nets, weavings of Ilocano cloth, Igorot weaving, piña \"barong Filipino,\" jusi and sinamay; (15) machine parts manufacture such as wheels and stone mortars; (15) poultry including ducks raising and \"balut\" making; (16) piggery; (17) home cigar making; (18) food preservation and canning, including the making of dried and/or smoked fish or meat, vinegar wine, lambanog, \"bagoong,\" pili or peanuts confectionery or coconut candy (bucayo); (19) other related crafts such as making of brooms, pandan, nito and buri bags, \"karagomoy\" bags, bead making, guitar and other musical instruments; and (20) such other industries done in the home with the aid of electrical gadgets and/or by hand manipulation. All cottage industries shall be owned and operated by Filipino citizens, or by a corporation, partnership or cooperative, at least seventy-five per cent of the capital or investment of which is owned by Filipino citizens. All members of its Board of Directors shall be Filipino citizens.\n\"The word capitalization as used in this section shall mean the total current assets and fixed assets, excluding the value of the land and building if the same are the residence of the owner, but including machinery and equipment, land and building leased, rented and/or used at least six months of each year. For purposes of this Act, any and all branches, agencies; outlets or divisions of a licensed cottage industry shall be collated to determine the capitalization thereof.\n\"The term \"cottage industry products\" shall mean products produced by cottage industries and shall be labeled, if feasible, as Cottage Industry Products Made in the Philippines, together with the identity of the producer."}},{"id":"PH-H4128-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section sixteen of the same Act is also amended to read as follows:\n\"Sec. 16. The production, manufacture and sale of cottage industry products shall be exempt from all taxed, except specific and income taxes, for a period of five years from the date of registration of the person or firm engaged in the production or manufacture of cottage industry products with the Board: Provided, That seventy-five per cent of the total cost of raw materials utilized in the production or manufacture of cottage industry products consists of raw materials of Philippine origin: Provided, further, That the latter requirement as to raw materials shall not apply to embroidery, piggery, poultry, livestock and metal craft industries: Provided, Furthermore, That no exemptions from the percentage taxes on sales shall be enjoyed for all sales in excess of two hundred thousand pesos each year: Provided, finally, That the provisions of the law on cooperatives shall not be affected by this Act.\n\"Any individual or corporation, partnership or association who or which subsequently sells, leases, pledges or otherwise transfers any machinery and equipment imported and exempted from the tax as provided for in this Act, to another likewise engaged in the cottage industry, shall pay the corresponding duties and taxes thereon: Provided, However, That if the transfer is made in favor of another not engaged in the cottage industry, the duties and taxes shall be double the rates provided for under existing laws, all such transactions shall be made with the knowledge of the NACIDA and the Commissioner of Customs.\n\"Any person or firm duly registered and engaged in the promotion, manufacture and sale of cottage industry, products prior to the approval of this Act, whose capitalization is more than fifteen thousand pesos shall continue to enjoy the tax exemptions provided herein only for a period not exceeding three months from the date of the approval of this Act until the expiration of five years from the date such person or firm was registered to the Board whichever period comes first.\""}},{"id":"PH-H4128-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Submission of Report. The Secretary of Commerce and industry shall submit an annual report on the amount of taxes waived for each fiscal year for each of the different registered cottage industries of the NACIDA to the Presiding Officers of both Houses of Congress thirty days before the opening of its regular session."}},{"id":"PH-H4128-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Certain Sections of Republic Act Numbered Three Thousand Four Hundred Seventy","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4129"] = {"id":"PH-H4129","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5327_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第4437号共和国法（即《授予Batac Consolidated Facoma，Inc.在北伊罗戈省Batac市镇建设、维护与运营无线电广播电台许可》）的法案","en":"An Act Amending Republic Act Numbered Forty-Four Hundred Thirty-Seven, Entitled, \"An Act Granting Batac Consolidated Facoma, Inc. a Permit to Construct, Maintain and Operate a Radio Broadcasting Station in the Municipality of Batac, Province of Ilocos Norte\"","orig":"An Act Amending Republic Act Numbered Forty-Four Hundred Thirty-Seven, Entitled, \"An Act Granting Batac Consolidated Facoma, Inc. a Permit to Construct, Maintain and Operate a Radio Broadcasting Station in the Municipality of Batac, Province of Ilocos Norte\"","vi":"Đạo luật sửa đổi Đạo luật Cộng hòa số 4437","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติแห่งสาธารณรัฐที่ 4437","id":"Undang-Undang mengubah Undang-Undang Republik No. 4437","ms":"Akta meminda Akta Republik No. 4437"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5327","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5327_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4129-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Forty-four hundred thirty-seven amended to read as follows:\n\"Sec. 1. Subject to the provisions of the Constitution as well as of Act Numbered Thirty-eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Thirty-nine hundred and ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred and forty-six, known as the Public Service Act, and their amendments and other applicable laws, Batac Consolidated Facoma, Inc., is hereby granted a permit to construct, maintain and operate, for commercial purposes and in the public interest, to cover Northern Luzon areas a radio-television station in the Municipality of Batac, Province of Ilocos Norte: Provided, That this permit shall be void unless the construction of said radio-television station is begun within two years from approval of this amendatory Act: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the station herein authorized, to reach the population on important issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use said station for broadcasting/exhibiting obscene or indecent language or speech or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage or assist in subversive or treasonable acts.\""}},{"id":"PH-H4129-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Republic Act Numbered Forty-Four Hundred Thirty-Seven, Entitled, \"An Act Granting Batac Consolidated Facoma, Inc. a Permit to Construct, Maintain and Operate a Radio Broadcasting Station in the Municipality of Batac, Province of Ilocos Norte\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4130"] = {"id":"PH-H4130","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5328_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为 Naga 市市法院增设一名法官，并为此修订该市宪章第75条的法案","en":"An Act Providing One Additional Judge for the City Court of the City of Naga, Amending for the Purpose Section Seventy-Five of the Charter of Said City","orig":"An Act Providing One Additional Judge for the City Court of the City of Naga, Amending for the Purpose Section Seventy-Five of the Charter of Said City"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 5328","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5328_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4130-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of Section seventy-five of Republic Act Numbered Three hundred five, otherwise known as the Charter of the City of Naga, is hereby amended to read as follows:\n\"Sec. 75. Regular, auxiliary and acting judges of city court.— There shall be a city court for the City of Naga, for which there shall be appointed two city judges and auxiliary city judge.\""}},{"id":"PH-H4130-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing One Additional Judge for the City Court of the City of Naga, Amending for the Purpose Section Seventy-Five of the Charter of Said City","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4131"] = {"id":"PH-H4131","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5329_1968.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Abuyog市","en":"An Act Establishing a Stock Farm in the Municipality of Abuyog, Province of Leyte, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing a Stock Farm in the Municipality of Abuyog, Province of Leyte, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 5329","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5329_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4131-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established under the supervision of the Director of Animal Industry, an animal stock farm in the Municipality of Abuyog, Province of Leyte, at a suitable site that may be reserved or acquired for the purpose."}},{"id":"PH-H4131-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Animal Industry, with the approval of the Secretary of Agriculture and Natural Resources, shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H4131-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of two hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said stock farm for the fiscal year nineteen hundred sixty-nine. Thereafter, such sums as may be needed for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H4131-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58"};
  FT["PH-H4132"] = {"id":"PH-H4132","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5330_1968.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"授予 Genaro U. Aventajado 在莱特省 Babatngon 市镇建设、维护和运营制冰厂与冷藏库并在该市镇销售冰和供应冷藏的特许权法案","en":"An Act Granting Genaro U. Aventajado a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the Municipality of Babatngon, Province of Leyte, and to Sell Ice and Supply Cold Storage Within Said Municipality","orig":"An Act Granting Genaro U. Aventajado a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the Municipality of Babatngon, Province of Leyte, and to Sell Ice and Supply Cold Storage Within Said Municipality","vi":"Đạo luật cấp đặc quyền cho Genaro U. Aventajado để xây dựng, duy trì và vận hành nhà máy nước đá và kho lạnh tại Thị trấn Babatngon, Tỉnh Leyte, và bán nước đá và cung cấp dịch vụ kho lạnh","th":"พระราชบัญญัติให้สัมปทานแก่ Genaro U. Aventajado ในการก่อสร้าง บำรุงรักษา และดำเนินการโรงงานน้ำแข็งและห้องเย็นในเทศบาล Babatngon จังหวัด Leyte และจำหน่ายน้ำแข็งและให้บริการห้องเย็น","id":"Undang-Undang memberikan konsesi kepada Genaro U. Aventajado untuk membangun, memelihara, dan mengoperasikan pabrik es dan penyimpanan dingin di Kotamadya Babatngon, Provinsi Leyte, dan menjual es serta menyediakan layanan penyimpanan dingin","ms":"Akta memberikan konsesi kepada Genaro U. Aventajado untuk membina, menyelenggarakan dan mengendalikan kilang ais dan stor sejuk di Perbandaran Babatngon, Wilayah Leyte, dan menjual ais serta menyediakan perkhidmatan stor sejuk"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5330","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5330_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4132-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in this Act and in Commonwealth Act Numbered One hundred forty-six, as amended, Act Numbered Thirty six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to Genaro U. Aventajado for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an ice plant and cold storage in the Municipality of Babatngon, Province of Leyte, for the purpose of manufacturing ice for distribution and sale, and supplying cold storage within the said municipality, and to charge and collect a schedule of rates and prices therefor, which shall at all times be subject to regulations by the Republic Service Commission or its legal successor."}},{"id":"PH-H4132-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall manufacture and supply ice up to the limit of the capacity of his plant, said limit to be determined by the Public Service Commission."}},{"id":"PH-H4132-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the apparatus and appurtenances to be used by the grantee shall be modern, safe and first class in every respect. The grantee, whenever the Public Service Commission determines that public interest reasonably requires it, shall change or alter any of the apparatus and appurtenances at his expense."}},{"id":"PH-H4132-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"If the grantee shall not commence the construction of his plant within two years from the approval of this Act, unless prevented by an act of God or force majeure, martial law, riot, civil commotion, usurpation by a military power or any other cause beyond the grantee's control, this franchise shall become null and void."}},{"id":"PH-H4132-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is granted with the understanding and upon the condition that it shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H4132-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the Auditor General, and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts for the quarter past."}},{"id":"PH-H4132-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"In the event of any competing person, natural or juridical, receiving from the Congress of the Philippines a similar franchise in which there should be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of such competing person."}},{"id":"PH-H4132-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Genaro U. Aventajado a Franchise to Construct, Maintain and Operate an Ice Plant and Cold Storage in the Municipality of Babatngon, Province of Leyte, and to Sell Ice and Supply Cold Storage Within Said Municipality","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4133"] = {"id":"PH-H4133","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5331_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of One Hundred Twenty-Five Thousand Pesos to Implement Republic Act Numbered Forty-Two Hundred Seventy-Three and for the Payment of the Salaries of Personnel","orig":"An Act Appropriating the Sum of One Hundred Twenty-Five Thousand Pesos to Implement Republic Act Numbered Forty-Two Hundred Seventy-Three and for the Payment of the Salaries of Personnel"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5331","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5331_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4133-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of one hundred thousand pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, to implement Republic Act Numbered Forty-two hundred seventy-three, and the sum of twenty-five thousand pesos is likewise appropriated for the payment of the salaries of personnel for the fiscal year nineteen hundred sixty-nine. Such sum as may be needed for the operation of the San Joaquin Breeding Station in the Municipality San Joaquin, Province of Iloilo, in subsequently years shall be included in the annual General Appropriations Act."}},{"id":"PH-H4133-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58"};
  FT["PH-H4134"] = {"id":"PH-H4134","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5332_1968.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"授予 Jaro Liberty 电力公司在莱特省 Jaro 市镇安装、维护和运营电灯、热力、动力系统与制冰厂，并将其系统与售冰业务扩展至该省其他市镇的特许权法案","en":"An Act Granting the Jaro Liberty Electric Company, Inc. a Franchise to Install, Maintain and Operate Electric Light, Heat, Power System and Ice Plant in the Municipality of Jaro, Province of Leyte, and to Extend its Electric Light, Heat and Power System and Distribution of Ice for Sale to the Municipalities of Tunga, Alangalang, Santa Fe and Pastrana, that Province","orig":"An Act Granting the Jaro Liberty Electric Company, Inc. a Franchise to Install, Maintain and Operate Electric Light, Heat, Power System and Ice Plant in the Municipality of Jaro, Province of Leyte, and to Extend its Electric Light, Heat and Power System and Distribution of Ice for Sale to the Municipalities of Tunga, Alangalang, Santa Fe and Pastrana, that Province","vi":"Đạo luật cấp quyền khai thác cho Jaro Liberty Electric Company, Inc. để xây dựng, lắp đặt, vận hành và duy trì hệ thống điện tại thị xã Jaro, tỉnh Leyte","th":"พระราชบัญญัติให้สัมปทานแก่ Jaro Liberty Electric Company, Inc. เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบไฟฟ้าในเทศบาล Jaro, จังหวัด Leyte","id":"Undang-Undang memberikan waralaba kepada Jaro Liberty Electric Company, Inc. untuk membangun, memasang, mengoperasikan, dan memelihara sistem tenaga listrik di Kotamadya Jaro, Provinsi Leyte","ms":"Akta memberikan francais kepada Jaro Liberty Electric Company, Inc. untuk membina, memasang, mengendalikan dan menyelenggara sistem tenaga elektrik di Perbandaran Jaro, Wilayah Leyte"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5332","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5332_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4134-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions imposed by this Act and in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is hereby granted to the Jaro Liberty Electric Company, Inc., for a period of twenty-five years from the approval of this Act, the right, privilege and authority to install, maintain and operate electric light, heat, power system and ice plant in the Municipality of Jaro, Province of Leyte, and to extend its electric light, heat, power system and distribution of ice for sale to the municipalities of Tunga, Alangalang, Santa Fe and Pastrana, that province, for the purpose of generating and distributing electric light, heat and/or power and ice for sale in said municipalities."}},{"id":"PH-H4134-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For the purpose of this Act, the grantee shall have the right to harness and develop the Cabayungan River in the Municipality of Jaro, Province of Leyte, for hydroelectric power. The grantee shall further have the right and privilege to install, lay and maintain on all streets, public thoroughfares, bridges and public places with said units, poles, wires, transformers, capacitors, overhead protective devices, and pole line hardware, and other equipment necessary for the safe distribution of electric current to the public. Furthermore, the grantee shall have the right and privilege to buy and import spare parts, vehicles and machinery solely for the use and operation maintenance of the company and/or corporation: Provided, However, That the grantee may not sell or dispose of any vehicle or machinery imported under this Act within five years from the date of its purchase without the vendee paying the corresponding tax for the said machinery or vehicle."}},{"id":"PH-H4134-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall manufacture and supply ice up to the limit of the capacity of its plant, said limit to be determined by the Public Service Commission."}},{"id":"PH-H4134-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The books, records and accounts of the grantee shall always be open to the inspection of the Auditor General or his authorized representatives and it shall be the duty of the grantee to submit to the Auditor General quarterly reports in duplicate showing the gross receipts for the quarter past."}},{"id":"PH-H4134-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In the event of any competing individual, association of persons or corporation receiving from the Congress of the Republic of the Philippines a similar franchise on which there shall be any terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, association of persons or corporation."}},{"id":"PH-H4134-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A consideration of the franchise and rights hereby granted, the grantee shall pay a franchise tax equal to five per centum of the gross earnings for electric current sold under this franchise of which the two per centum shall accrue to the National Government and the other three per centum to the municipality where the franchise is being operated."}},{"id":"PH-H4134-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Jaro Liberty Electric Company, Inc. a Franchise to Install, Maintain and Operate Electric Light, Heat, Power System and Ice Plant in the Municipality of Jaro, Province of Leyte, and to Extend its Electric Light, Heat and Power System and Distribution of Ice for Sale to the Municipalities of Tunga, Alangalang, Santa Fe and Pastrana, that Province","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4135"] = {"id":"PH-H4135","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5333_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将安蒂克省 Dao市镇 Dao 急诊医院的名称变更为Tobias Fornier 纪念医院的法案","en":"An Act Changing the Name of the Dao Emergency Hospital in the Municipality of Dao, Province of Antique, to Tobias Fornier Memorial Hospital","orig":"An Act Changing the Name of the Dao Emergency Hospital in the Municipality of Dao, Province of Antique, to Tobias Fornier Memorial Hospital","vi":"Đạo luật đổi tên Dao Emergency Hospital tại Thị trấn Dao, Tỉnh Antique thành Bệnh viện tưởng niệm Tobias Fornier","th":"พระราชบัญญัติเปลี่ยนชื่อ Dao Emergency Hospital ในเทศบาล Dao, จังหวัด Antique เป็นโรงพยาบาลอนุสรณ์ Tobias Fornier","id":"Undang-Undang mengubah nama Dao Emergency Hospital di Kotamadya Dao, Provinsi Antique menjadi Rumah Sakit Peringatan Tobias Fornier","ms":"Akta menukar nama Dao Emergency Hospital di Perbandaran Dao, Wilayah Antique menjadi Hospital Peringatan Tobias Fornier"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5333","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5333_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4135-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Dao Emergency Hospital in the Municipality of Dao, Province of Antique, is hereby changed and hereafter to be known as the Tobias Fornier Memorial Hospital."}},{"id":"PH-H4135-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Dao Emergency Hospital in the Municipality of Dao, Province of Antique, to Tobias Fornier Memorial Hospital","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4136"] = {"id":"PH-H4136","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5334_1968.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"为菲律宾大学亚洲中心的建筑物、设备与设施提供经费并为其他目的法案","en":"An Act Providing Funds for Buildings, Equipment, and Facilities of the Asian Center of the University of the Philippines, and for Other Purposes","orig":"An Act Providing Funds for Buildings, Equipment, and Facilities of the Asian Center of the University of the Philippines, and for Other Purposes"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5334","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5334_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4136-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is hereby declared as a national policy to develop a closer and broader contact with or Asian neighbors in the field of learning and scholarship to attain knowledge of our national identity in relation to other Asian nations through profound studies on Asian cultures, histories, social forces and aspirations."}},{"id":"PH-H4136-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Pursuant to this policy, there is hereby established an Asian Center in the University of the Philippines, which shall absorb the present Institute of Asian Studies, its personnel and facilities: Provided, That such center shall give primary emphasis on Philippine studies."}},{"id":"PH-H4136-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of two million and five hundred thousand pesos, for the construction of the necessary buildings in the present site of the University of the Philippines, Diliman, Quezon City, and the purchase of equipment and other facilities needed for teaching, research and field work. Furthermore, there is hereby appropriated the additional sum of one hundred thousand pesos annually out of any funds in the National Treasury for continuous support to the Asian Center."}},{"id":"PH-H4136-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The University of the Philippines may, for the purposes of teaching, research, field work, and other activities of the Asian Center, obtain the services of scholars and technical personnel of any agency of the Philippine Government to provide instruction, perform research or field work and other activities as may be needed. Such personnel may be given honorarium by the University of the Philippines upon recommendation of the Director of the Asian Center, any law to the contrary notwithstanding."}},{"id":"PH-H4136-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing Funds for Buildings, Equipment, and Facilities of the Asian Center of the University of the Philippines, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4137"] = {"id":"PH-H4137","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5335_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Libertad市","en":"An Act Declaring the Swamp Reservation in the Municipality of Libertad, Province of Misamis Oriental, as Alienable and Disposable Land and Conveying the Same in Favor of the Aforementioned Municipality to be Used as Permanent Sites for its Public Market, Municipal Hall and Other Public Buildings","orig":"An Act Declaring the Swamp Reservation in the Municipality of Libertad, Province of Misamis Oriental, as Alienable and Disposable Land and Conveying the Same in Favor of the Aforementioned Municipality to be Used as Permanent Sites for its Public Market, Municipal Hall and Other Public Buildings"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5335","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5335_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4137-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Libertad Swamp Reservation situated in the Municipality of Libertad, Province of Misamis Oriental, is hereby declared as alienable and disposable land and is hereby conveyed in favor of the aforementioned municipality to be used as permanent sites for its public market, municipal hall and other public buildings."}},{"id":"PH-H4137-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58"};
  FT["PH-H4138"] = {"id":"PH-H4138","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5336_1968.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"修订联邦法第 294 号（即规范菲律宾机械工程执业并为机械厂操作人员发照的法案）若干条款的法案","en":"An Act Amending Commonwealth Act Numbered Two Hundred Ninety-Four, as Amended, Entitled \"An Act to Regulate the Practice of Mechanical Engineering in the Philippines, to Provide for Licensing the Operating Personnel in Mechanical Plants and for Other Purposes\"","orig":"An Act Amending Commonwealth Act Numbered Two Hundred Ninety-Four, as Amended, Entitled \"An Act to Regulate the Practice of Mechanical Engineering in the Philippines, to Provide for Licensing the Operating Personnel in Mechanical Plants and for Other Purposes\"","vi":"Đạo luật sửa đổi Đạo luật Thịnh vượng chung số 294 như đã được sửa đổi, và cho các mục đích khác","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติเครือรัฐที่ 294 ซึ่งแก้ไขเพิ่มเติมแล้ว และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang mengubah Undang-Undang Persemakmuran No. 294 sebagaimana diubah, dan untuk tujuan lain","ms":"Akta meminda Akta Komanwel No. 294 sebagaimana dipinda, dan untuk tujuan lain"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5336","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5336_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4138-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subparagraph two of section four of Commonwealth Act Numbered Two hundred ninety four, otherwise known as the \"Mechanical Engineering Law\" is hereby amended to read as follows:\n\"(2) Hold the degree of M.E. or B.S.M.E. or M.M.E. or M.S.M.E., or the equivalent thereof, conferred by an engineering school or college, legally chartered and of recognized standing.\""}},{"id":"PH-H4138-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section eight of the same Act is hereby amended to read as follows:\n\"Sec. 8. Compensation of Board. — The members of the Board shall each receive as compensation the sum of ten pesos for each applicant examined or registered without examination for any of the first two grades provided under Section eleven hereof; and five pesos for each applicant registered without examination or examined for the grade of certified plant mechanic: Provided, That the total amount shall not exceed the sum of eighteen thousand pesos per annum. Any mechanical engineer in the service of the Government of the Philippines appointed as member of the Board shall receive the compensation herein provided, in addition to his salary. All fees shall be received by the officer designated by competent authority as the collecting officer for the Civil Service Commission, and such officer shall pay all authorized expenses of the Board, including the compensation provided for by this Act for the members of the Board."}},{"id":"PH-H4138-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section eleven of the same Act is hereby amended to read as follows:\n\"Sec. 11. Grades. — Certificates of registration for the practice of mechanical engineering shall be of three grades and in the order of rank as follows:\n(1) professional mechanical engineer,\n(2) mechanical engineer, and\n(3) certified plant mechanic.\""}},{"id":"PH-H4138-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Paragraph (a) of Section thirteen of the same Act is hereby amended to read as follows:\n\"Sec. 13. Definition of terms.— (a) Mechanical engineering. — A person shall be deemed to be practicing mechanical engineering or rendering mechanical engineering service within the meaning and intent of this Act, who shall, for a fee, salary or other reward or compensation paid to himself or to another person, or even without such reward or compensation, render professional mechanical engineering service in the form of consultation, investigation, valuation, planning, design, or preparation of specifications or estimates for, or take charge of management, administration and supervision of the construction, erection, installation or alteration of, or render engineering service in connection with the manufacture, sale, supply or distribution of, or to manage, operate, tend or maintain any mechanical equipment machinery or process, for any mechanical works, project or plant; or who shall, by means of signs, cards, advertisement or in any other way, offer to practice mechanical engineering or to render professional mechanical engineering service, or who shall in connection with his name, or otherwise, use, assume or advertise any title or description tending to convey the impression that he is a professional mechanical engineer, or mechanical engineer, or certified plant mechanic, or that he is engaged in the practice of mechanical engineering as defined in this Act.\""}},{"id":"PH-H4138-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Subparagraphs (c) and (d-1) of Section sixteen of the same Act is hereby amended to read as follows:\n\"(c) That he is a registered mechanical engineer under the provisions of this Act.\n\"(d) That he has graduated from an engineering school or college of recognized standing, after completing an approved course in mechanical engineering of not less than four years; and that after he has been conferred a degree as provided in Section eighteen of this Act he has a specific record of a total of four years or more of active practice in mechanical engineering work of a character satisfactory to the Board, and in an affidavit by one or more registered professional mechanical engineers indicate that the applicant is competent to practice as professional mechanical engineer.\n\"In considering the qualifications of applicants, being in charge of mechanical engineering teaching in an engineering school of recognized standing may be regarded as being in active practice in mechanical engineering work.\""}},{"id":"PH-H4138-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Subparagraph (d-2) of Section sixteen and Section seventeen of the same Act are hereby repealed."}},{"id":"PH-H4138-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section eighteen of the same Act is hereby amended to read as follows:\n\"Sec. 18. Qualifications of applicant for mechanical engineer. — Any person applying for examination and for a certificate of registration as mechanical engineer shall, prior to admission to examination, establish to the satisfaction of the Board:\n\"(a) That he is at least eighteen years of age: Provided, That no license shall be issued to him until he reaches the age of twenty-one.\n\"(b) That he is of good reputation and moral character.\n\"(c) That he holds the degree of bachelor of science in mechanical engineering, mechanical engineer, master in mechanical engineering, master of science in mechanical engineering, or the equivalent thereof, conferred by a university, school, college, academy or institute duly constituted and recognized as such by the government or the state in which it is established after completing a collegiate course of not less than four years.\""}},{"id":"PH-H4138-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Sections twenty-one, twenty-four, and twenty-five of the same Act, as emended, are hereby amended to read as follows:\n\"Sec. 21. Scope of examinations. — The examination for professional mechanical engineer shall be testimonial which shall consist of a submission of an enumeration of the applicant's experiences including the presentation of an engineering report pertinent to his line of experience attested to by one or more professional mechanical engineers duly notarized to the satisfaction of the Board.\n\"The scope of the examinations and the methods of procedure shall be prescribed by the Board with special reference to the applicant's ability to do the class of engineering work pertaining to the particular grade he is to be registered for, and to prove that said applicant has sufficient technological knowledge to insure safety to life, health and property as well as economy and efficiency in the design, construction, installation, maintenance, operation, organization and management of mechanical plants or works. It shall be the duty of the Board to prepare the programs of examinations and to publish the same at least six months before the date of the examinations wherein they are to be used.\n\"Any alteration or amendments that the Board may later wish to introduce in said program shall also be published at least six months before the date of the examinations.\n\"Sec. 24. Registration as professional mechanical engineer without examination. — No examination shall be required of any person who shall, with his application for registration as professional mechanical engineer submitted to the Board after the date this Act becomes effective, present evidence or other proof satisfactory to the Board, showing that, on the date of the approval of this Act, he was a mechanical engineer duly licensed by the Board of Examiners for Mechanical Engineers under Act Numbered Two thousand nine hundred eighty-five of the Philippine Legislature of nineteen hundred twenty-one, as amended.\n\"Sec. 25. Registration as mechanical engineer without examination. — No examination shall be required of any person who shall, with his application for registration as mechanical engineer, submitted to the Board the date this Act becomes effective, present evidence or sufficient proof satisfactory to the Board, showing that, on the date of the approval of this Act, as amended, he was a junior mechanical engineer duly registered by said Board under the original provisions of this Act.\""}},{"id":"PH-H4138-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section twenty-six of the same Act is hereby repealed."}},{"id":"PH-H4138-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Sections twenty-eight, thirty, thirty-six, thirty-seven, thirty-eight, thirty-nine and forty-one of the same Act, as amended, are hereby amended to read as follows:\n\"Sec. 28. Issuance of certificates. — The Board shall issue a certificate of registration upon payment of the registration fee as provided for in this Act, to any applicant who, in the opinion of the Board and after approval of his ratings by the Office of the President, has satisfactorily met all the requirements specified in this Act for the particular grade for which he is registering.\n\"All certificates of registration shall show the full name of the registrant, shall have a serial number, and shall be signed by all the members of the Board and the Commissioner of Civil Service, and shall be attested by the official seal.\n\"The issuance of a certificate of registration by the Board to a registrant shall be evidence that the person named therein is entitled to all the rights and privileges of a registered professional mechanical engineer, mechanical engineer, certified plant mechanical, as the case may be, while said certificate remains unrevoked or unsuspended.\n\"Sec. 30. Fees for examination and registration. — Every applicant for examination for the grade of professional mechanical engineer or mechanical engineer shall pay an examination fee of fifty pesos; and for the grade of certified plant mechanic, a fee of twenty pesos; which fee shall accompany the application.\n\"Every registrant for the grades of professional mechanical engineer and mechanical engineer shall pay a registration fee of ten pesos; and for certified plant mechanic, a fee of five pesos: Provided, That when an applicant is registered, without examination, for the grade of professional mechanical engineer or of mechanical engineer, he shall be required to pay a registration fee of thirty pesos; and for the grade of certified plant mechanic, a fee of ten pesos.\n\"Sec. 36. Field of action authorized for each grade; prohibitions. — It shall be unlawful for any person, unless exempted from registration under Section fourteen of this Act:\n\"(a) To be in responsible charge of the preparation of plans, designs, investigation, valuation, technical reports, specifications, or estimates, or to be in performance of other professional mechanical engineering service for any mechanical works, project or plant, either for himself or for others, unless he holds a valid certificate of registration as professional mechanical engineer.\n\"(b) To be in responsible charge of the construction, erection, installation or alteration or of the performance of mechanical engineering service in connection with the manufacture, sale, supply or distribution of any mechanical equipment, machinery or process for any mechanical works, project or plant, either for himself or for others, unless he holds a valid certificate of registration as professional mechanical engineer or mechanical engineer.\n\"(c) To operate, tend, or maintain, or be in charge of the operation, tending, or maintenance of any mechanical equipment, machinery or process for any mechanical works, project or plant of fifty horsepower or more but of less than three hundred horsepower, unless he holds a valid certificate of registration as professional mechanical engineer, mechanical engineer, or certified plant mechanic.\n\"(d) To operate, tend, or maintain, or be in charge of the operation, tending or maintenance of any mechanical equipment, machinery or process for any mechanical works, project or plant of three hundred horsepower or more, unless he holds a valid certificate of registration as professional mechanical engineer, or mechanical engineer.\n\"Sec. 37. Personnel required in mechanical plants. — Every mechanical works, project, or plant, in operation shall have not less than the following complement of resident engineers or mechanics duly registered under this Act:\n\"(a) Fifty horsepower or over but below three hundred horsepower, one certified plant mechanic, or one mechanical engineer of any rank: Provided, That every mechanical works, project or plant of fifty horsepower or over but below three hundred horsepower operating in more than one shift every twenty-four hours, shall have, in addition to the minimum personnel herein required, one certified plant mechanic or one mechanical engineer of any rank in charge or each and every additional shift.\n\"(b) Three hundred horsepower or over, one mechanical engineer or one professional mechanical engineer: Provided, That every mechanical works, projects or plants of three hundred horsepower or more shall have at least one resident mechanical engineer or professional mechanical engineer, in charge of each shift.\n\"Sec. 38. Preparation of plans and supervision of construction by registered engineers required.— It shall be unlawful for any person to order or otherwise cause the construction, erection, installation, or alteration of any mechanical equipment, machinery or process for any mechanical works, project or plant of fifty horsepower or more, unless designs, plans, layouts, and/or specifications have been prepared under the responsible charge of, signed and sealed by a registered professional mechanical engineer, and unless the construction, erection, installation, and/or alteration thereof are executed under the responsible charge and direct supervision of a registered professional mechanical engineer, a registered mechanical engineer, or a person exempt from registration under subsection (c) or (d) of Section fourteen of this Act.\n\"Sec. 39. Application to firms and corporations. — A firm or a co-partnership, or a corporation, or an association may engage in the practice of mechanical engineering in the Philippines, provided only that such practice is carried on by professional mechanical engineers, or mechanical engineers, or certified plants mechanics, holding valid certificates of registration issued by the Board.\n\"In the case of a firm, co-partnership, corporation, association, society or company, the manager, administrator, or the person who has charge of the management or administration of the business shall be held personally liable for any violation of this Act.\n\"Sec. 41. Roster of engineers and mechanics. — A roster showing the names and places of business of all registered professional mechanical engineers, mechanical engineers, or certified plant mechanics, shall be prepared by the Commissioner of Civil Service during the months of January and July of each year, commencing one year from the date this Act becomes effective. Copies of this roster shall be mailed to each person so registered, placed on file with the Board and copies furnished to all Department Heads, to the Mayors of all chartered cities, to the Director of Public Works, to such other bureaus, governmental agencies, and municipal and provincial authorities as may be deemed necessary, and to the public upon request.\""}},{"id":"PH-H4138-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The same Act is further amended by inserting a new section between Section forty-seven and Section forty-eight, to be known as Section forty-seven-A which shall read as follows:\n\"Sec. 47-A. Transitory Provision— Subjects Mechanical Plant Engineer. — Effective upon approval of this Act, the original grade of mechanical plant engineer shall retain their original certificate and shall continue to practice as such with the following field of action:\n\"To be in responsible charge of the construction, erection, installation or alteration or of the performance of engineering service in connection with maintenance, sale, supply or distribution of any mechanical equipment, machinery or process for any mechanical works, project or plant, either for himself or for others and all the rights and privileges of mechanical engineer as provided in this Act, as amended.\""}},{"id":"PH-H4138-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Commonwealth Act Numbered Two Hundred Ninety-Four, as Amended, Entitled \"An Act to Regulate the Practice of Mechanical Engineering in the Philippines, to Provide for Licensing the Operating Personnel in Mechanical Plants and for Other Purposes\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4139"] = {"id":"PH-H4139","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5337_1968.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Gabriel P. Formoso 在菲律宾境内建设、维护和运营私人固定点对点、陆基与陆上移动无线电台的临时许可的法案","en":"An Act Granting Gabriel P. Formoso a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Gabriel P. Formoso a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","vi":"Đạo luật cấp giấy phép tạm thời cho Gabriel P. Formoso để xây dựng, duy trì và vận hành trạm vô tuyến cố định điểm-điểm, trên mặt đất và di động mặt đất tư nhân để nhận và truyền thông tin vô tuyến tại Philippines","th":"พระราชบัญญัติให้ใบอนุญาตชั่วคราวแก่ Gabriel P. Formoso ในการก่อสร้าง บำรุงรักษา และดำเนินการสถานีวิทยุแบบจุดต่อจุดประจำที่、ภาคพื้นดินและเคลื่อนที่ภาคพื้นดินของเอกชนสำหรับรับและส่งการสื่อสารทางวิทยุในฟิลิปปินส์","id":"Undang-Undang memberikan izin sementara kepada Gabriel P. Formoso untuk membangun, memelihara, dan mengoperasikan stasiun radio titik-ke-titik tetap, berbasis darat dan mudah alih darat swasta untuk penerimaan dan pengiriman komunikasi radio di Filipina","ms":"Akta memberikan permit sementara kepada Gabriel P. Formoso untuk membina, menyelenggarakan dan mengendalikan stesen radio titik-ke-titik tetap, berasas darat dan mudah alih darat persendirian untuk penerimaan dan penghantaran komunikasi radio di Filipina"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5337","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5337_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4139-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Gabriel P. Formoso, a temporary permit to construct, maintain and operate at such places in the Philippines as the grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed to point-to-point and land-based and land-mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided radio transmitting and radio receiving apparatus."}},{"id":"PH-H4139-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the government has not established similar service at the places selected by the grantee and is granted upon the express condition that the same shall be void unless the construction or installation of said stations be begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H4139-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, his successors or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain and operate private radio stations in such places within the Philippines as the interest of the grantee may justify."}},{"id":"PH-H4139-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee's business only."}},{"id":"PH-H4139-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, his successors or assigns, shall so construct, and operate his radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H4139-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, his successors or assigns, shall hold the national, provincial, city and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or person, caused by the construction or operation of his radio stations."}},{"id":"PH-H4139-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, his successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H4139-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, his successors or assigns, is authorized to operate his private radio stations in the medium frequency, high frequency, and very high frequency that may be assigned to him by the Secretary of Public Works and Communications."}},{"id":"PH-H4139-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, or the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company or corporation organized for the same purpose, without the previous approval of the Congress of the Philippines. Any corporation to which this temporary permit may be sold, transferred, or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H4139-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee's radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H4139-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided."}},{"id":"PH-H4139-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Gabriel P. Formoso a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land-Based and Land-Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4140"] = {"id":"PH-H4140","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5338_1968.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定菲律宾武装部队护士部队的职业激励措施，授权为此拨款并为其他目的法案","en":"An Act Providing Career Incentives in the Nurse Corps of the Armed Forces of the Philippines, Authorizing the Appropriation of Funds Therefor, and for Other Purposes","orig":"An Act Providing Career Incentives in the Nurse Corps of the Armed Forces of the Philippines, Authorizing the Appropriation of Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 5338","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5338_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4140-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Hereafter, any officer in the Nurse Corps of the Armed Forces of the Philippines on active duty shall receive one hundred pesos monthly as an incentive pay, in addition to the salary and other allowances she is entitled to receive under existing laws and regulations: Provided, That such incentive pay shall not accrue in her favor in time of war or declared national emergency, or while said officer is receiving additional pay for overseas service involving war or under conditions approximating war: And Provided, further, That any officer in the Nurse Corps receiving or authorized to receive flight or sea duty pay has the option to receive the incentive pay authorized under this Act or the flight or sea duty pay, but in no case shall she be entitled to receive both."}},{"id":"PH-H4140-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of three hundred and fifty thousand pesos or so much thereof as may be necessary is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, to carry out the purpose of this Act."}},{"id":"PH-H4140-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing Career Incentives in the Nurse Corps of the Armed Forces of the Philippines, Authorizing the Appropriation of Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4141"] = {"id":"PH-H4141","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5339_1968.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"授权安蒂克省Sibalom市镇安蒂克工艺与贸易学校开设工业教育理学士与工业艺术学士学位课程并为此拨款的法案","en":"An Act Authorizing the Antique School of Arts and Trades, Municipality of Sibalom, Province of Antique, to Offer Courses Leading to the Degrees of Bachelor of Science in Industrial Education and Bachelor of Science in Industrial Arts, and Appropriating Funds Therefor","orig":"An Act Authorizing the Antique School of Arts and Trades, Municipality of Sibalom, Province of Antique, to Offer Courses Leading to the Degrees of Bachelor of Science in Industrial Education and Bachelor of Science in Industrial Arts, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 5339","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5339_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4141-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Antique School of Arts and Trades, Municipality of Sibalom, Province of Antique, is hereby authorized to offer courses leading to the degrees of Bachelor of Science in Industrial Education and Bachelor of Science in Industrial Arts, in addition to its present curriculum."}},{"id":"PH-H4141-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby appropriated, in addition to its present annual appropriation, out of any funds in the National Treasury not otherwise appropriated, to carry out the purpose of this Act, during the fiscal year nineteen hundred sixty-nine. Thereafter, such sums as may be needed for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H4141-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Antique School of Arts and Trades, Municipality of Sibalom, Province of Antique, to Offer Courses Leading to the Degrees of Bachelor of Science in Industrial Education and Bachelor of Science in Industrial Arts, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4142"] = {"id":"PH-H4142","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5340_1968.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将莱特省托洛萨市镇托洛萨中央社区学校的名称变更为Daniel Z. Romualdez纪念学校的法案","en":"An Act Changing the Name of Tolosa Central Community School in the Municipality of Tolosa, Province of Leyte, to Daniel Z. Romualdez Memorial School","orig":"An Act Changing the Name of Tolosa Central Community School in the Municipality of Tolosa, Province of Leyte, to Daniel Z. Romualdez Memorial School","vi":"Đạo luật đổi tên Tolosa Central Community School tại Thị trấn Tolosa, Tỉnh Leyte thành Daniel Z. Romualdez Memorial School","th":"พระราชบัญญัติเปลี่ยนชื่อ Tolosa Central Community School ในเทศบาล Tolosa, จังหวัด Leyte เป็น Daniel Z. Romualdez Memorial School","id":"Undang-Undang mengubah nama Tolosa Central Community School di Kotamadya Tolosa, Provinsi Leyte menjadi Daniel Z. Romualdez Memorial School","ms":"Akta menukar nama Tolosa Central Community School di Perbandaran Tolosa, Wilayah Leyte menjadi Daniel Z. Romualdez Memorial School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 5340","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5340_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4142-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Tolosa Central Community School in the municipality of Tolosa, Province of Leyte, is hereby changed to Daniel Z. Romualdez Memorial School."}},{"id":"PH-H4142-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Tolosa Central Community School in the Municipality of Tolosa, Province of Leyte, to Daniel Z. Romualdez Memorial School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4143"] = {"id":"PH-H4143","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5341_1968.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"为第十三司法区增设一名法官主持塔克洛班市初审法院，为此修订经修正的1948年《司法法》第50条与第52条的法案","en":"An Act Providing One Additional Judge for the Thirteenth Judicial District to Preside Over the Court of First Instance of the City of Tacloban, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948, as Amended","orig":"An Act Providing One Additional Judge for the Thirteenth Judicial District to Preside Over the Court of First Instance of the City of Tacloban, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948, as Amended"},"level":"law","status":"active","topics":["judiciary"],"docNumber":"Republic Act No. 5341","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5341_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4143-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The thirteenth paragraph of Section fifty of Republic Act Numbered Two hundred ninety-six, otherwise known as \"The Judiciary Act of 1948,\" as amended, is further amended to read as follows:\n\"Nineteen judges shall be commissioned for the Thirteenth Judicial District. Eight judges shall preside over the Courts of First Instance of Samar and Calbayog City and shall be known as the judges of the first, second, third, fourth, fifth, sixth, seventh and eighth branches thereof, respectively, and eleven judges shall preside over the Courts of First Instance of Leyte, Southern Leyte and the Cities of Ormoc and Tacloban, and shall be known as judges of the first, second, third, fourth, fifth, sixth, seventh, eighth, ninth, tenth and eleventh branches thereof, respectively."}},{"id":"PH-H4143-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The twelfth subparagraph of the second paragraph of Section fifty-two of the same Act, as amended, is further amended to read as follows:\n\"For the Thirteenth Judicial District, one judge shall be stationed in the Municipality of Catbalogan, Province of Samar; one judge, in the Municipality of Borongan, same province; one judge, in the Municipality of Laoang; same province; one judge, in the Municipality of Catarman, same province; one judge, in the City of Calbayog; one judge, in the Municipality of Guiuan, Province of Samar; one judge, in the Municipality of Allen, same province; and one judge, in the Municipality of Oras, same province; four judges shall be stationed in the City of Tacloban; one judge; in the Municipality of Maasin, Province of Southern Leyte; one judge, in the Municipality of San Juan, same province; one judge, in the City of Ormoc, who shall hold court sessions in the Municipality of Palompon at least two months every year; one judge, in the Municipality of Carigara, Province of Leyte; one judge, in the Municipality of Baybay same province; one judge, in the Municipality of Burauen, same province; and one judge, in the Municipality of Naval, Subprovince of Biliran: Provided, That one of the four branches of the Court of First Instance of Leyte stationed in the City of Tacloban shall exercise exclusive jurisdiction over all cases arising within the City of Tacloban as well as those cases arising from the First District of Leyte which may be assigned to it by the Secretary of Justice."}},{"id":"PH-H4143-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of sixty thousand pesos or so much thereof as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H4143-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing One Additional Judge for the Thirteenth Judicial District to Preside Over the Court of First Instance of the City of Tacloban, Amending for the Purpose Sections Fifty and Fifty-Two of the Judiciary Act of 1948, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4144"] = {"id":"PH-H4144","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5342_1968.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Palanan市","en":"An Act Establishing the Palanan Station Hospital in the Municipality of Palanan, Province of Isabela, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Establishing the Palanan Station Hospital in the Municipality of Palanan, Province of Isabela, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Trạm Palanan tại Đô thị Palanan, Tỉnh Isabela, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลสถานี Palanan ในเทศบาล Palanan จังหวัด Isabela และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Stasiun Palanan di Kotamadya Palanan, Provinsi Isabela, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Stesen Palanan di Perbandaran Palanan, Wilayah Isabela, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 5342","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5342_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4144-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"As defined in this Act, a station hospital shall mean a small hospital of not more than twenty-five bed-capacity for the management of common medical and maternity cases and surgical emergencies requiring ordinarily a short period of confinement. Cases requiring complicated major surgery and/or elaborate diagnostic examination or specialist treatment may not be confined in this hospital but transferred to regular provincial or regional hospitals."}},{"id":"PH-H4144-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"There is hereby established in the Municipality of Palanan, Province of Isabela, a station hospital to be known as the Palanan Station Hospital with a bed capacity of not less than ten or more than twenty-five beds."}},{"id":"PH-H4144-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Health shall cause the establishment of this hospital, provide a suitable table or organization of not more than fourteen personnel and promulgate rules and regulations for its maintenance and operation. He may, if the exigency of the service so demands, merge this hospital with local health units in the Municipality of Palanan, Province of Isabela, provided that the public health work of the latter unit will not be impaired."}},{"id":"PH-H4144-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The sum not to exceed fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, maintenance and operation of said hospital during the first fiscal year of its operation. Thereafter, such sums as may be needed, but not to exceed fifty thousand pesos, for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H4144-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58"};
  FT["PH-H4145"] = {"id":"PH-H4145","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1968/ra_5343_1968.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 Community Development Radio Corporation 在奎松省与东吕宋各省建设、维护和运营带边带无线电广播站的特许经营权法案","en":"An Act Granting the Community Development Radio Corporation a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations with Side Band in the Province of Quezon and in Eastern Luzon Provinces, Philippines","orig":"An Act Granting the Community Development Radio Corporation a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations with Side Band in the Province of Quezon and in Eastern Luzon Provinces, Philippines","vi":"Đạo luật cấp quyền khai thác cho Community Development Radio Corporation để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh tại tỉnh Quezon","th":"พระราชบัญญัติให้สัมปทานแก่ Community Development Radio Corporation เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงในจังหวัด Quezon","id":"Undang-Undang memberikan waralaba kepada Community Development Radio Corporation untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio di Provinsi Quezon","ms":"Akta memberikan francais kepada Community Development Radio Corporation untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio di Wilayah Quezon"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 5343","issuingBody":"Congress of the Philippines","promulgatedDate":"1968-06-15","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1968/ra_5343_1968.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4145-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, as well as Act Numbered Three thousand eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands and for other purposes;\" Act Numbered Three thousand nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, not inconsistent with this Act, the Community Development Radio Corporation is hereby granted a franchise to construct, maintain and operate radio broadcasting station with side band in the Province of Quezon and in eastern Luzon provinces, Philippines. The grantee shall have the right to establish relay stations and private point-to-point communication systems at such places in the Philippines as it may consider necessary and convenient."}},{"id":"PH-H4145-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date the said stations shall be put in operation, and is granted upon the express condition that the same shall be void unless the construction of said stations be begun within six months from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H4145-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise is likewise made upon the express condition that the grantee shall contribute to the public welfare; shall assist in the function of public information and education; shall conform to the ethics of honest enterprise; and shall not use its stations for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H4145-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee's radio broadcasting stations shall not be put in the actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequency and wave length to be used under this franchise and issued to the grantee a license for such use."}},{"id":"PH-H4145-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril or other national emergency and when public safety requires, to cause the closing of the grantee's radio stations or to authorize the use or possession thereof by any department of the Government without compensation to the grantee for the use of said stations during the continuance of the national emergency."}},{"id":"PH-H4145-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall be liable to pay the same taxes, unless exempted therefrom, on its real estate, buildings, and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay.\nThe grantee shall be liable to pay all other taxes under the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H4145-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H4145-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The franchise hereby grantees shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H4145-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"As a condition to the granting of this franchise, the grantee shall execute a bond in favor of the Government of the Philippines, in the sum of fifty thousand pesos, in form and with sureties satisfactory to the Secretary of Public Works and Communications, conditioned upon the faithful performance of the grantee's obligations hereunder during the first three years of the life of this franchise. If after three years from the date of acceptance of this franchise, the grantee shall have fulfilled said obligations, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications ."}},{"id":"PH-H4145-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Acceptance of this franchise shall be given in writing within six months after approval of this Act. When so accepted by the grantee and upon the approval of the bond aforesaid by the Secretary of Public Works and Communications, the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H4145-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company or corporation, organized for the same purpose, without the previous approval of the Congress of the Philippines. Any corporation to which this franchise may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H4145-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play or other matter to be broadcast from its stations, but if any such speech, play or other matter shall constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play or other matter: Provided, That the grantee, during any broadcast, shall cut off from the air the speech, play or other matter being broadcast, if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral, and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H4145-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This franchise shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H4145-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 15, 1968."}}],"pack":"ph-p58","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Community Development Radio Corporation a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations with Side Band in the Province of Quezon and in Eastern Luzon Provinces, Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
